(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.018-t*0.18)*20+Math.sin(x*0.014+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.35)*12+Math.cos((y+w1y)*0.02-t*0.3)*8;
  const w2y = Math.cos((y+w1y)*0.022-t*0.32)*12+Math.sin((x+w1x)*0.028+t*0.38)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.85],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.5+4)*40,0.14,1.3,0.7],
    [400+Math.cos(t*0.45+2)*70,200+Math.sin(t*0.65+1)*50,0.11,1.8,0.95],
    [200+Math.sin(t*0.55+6)*110,220+Math.cos(t*0.75+3)*70,0.05,2.8,1.15],
    [300+Math.cos(t*0.38+7)*90,30+Math.sin(t*0.58+5)*60,0.13,1.4,0.75]
  ];
  let act=0, inh=0, feed=0, cross=0;
  for (const [sX,sY,f,sp,wt] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const dc=1.0/(1.0+d*0.003);
    const w1=Math.sin(d*f-t*sp), w2=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    act+=w1*dc*wt; inh+=w2*dc*wt;
    feed+=Math.sin(d*f*1.3-t*sp*0.8+2)*dc*0.5;
    cross+=w1*w2*dc*0.15;
  }
  act/=6; inh/=6; feed/=6;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2-t*2)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.3+t*0.5)*Math.sin(sy*0.35-t*0.3)*0.15)*1.5)*0.3;
  const ripple=Math.sin(dist*0.12-t*3)*Math.exp(-dist*0.005)*0.4;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+feed*0.2+cross+ripple)*2.2);
  const blend=reaction*0.65+cell*0.2+cross*0.15, v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,35,85],[15,72,125],[25,135,145],[50,185,165],[130,215,185],[225,225,165],[245,185,105],[205,105,82],[145,52,72],[82,26,62],[32,15,52],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.75?1.2:(Math.abs(reaction)>0.5?1.05:1.0);
  const glow=(1.0-Math.abs(reaction)*0.2)*0.15+0.85;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*glow)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*glow)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*glow)|0
  ];
}
